package pe.edu.upeu.notificacion.repository; import org.springframework.data.jpa.repository.JpaRepository; import pe.edu.upeu.notificacion.entity.Notificacion; import java.util.*; public interface NotificacionRepository extends JpaRepository<Notificacion,Long>{List<Notificacion> findByUsuarioIdOrderByIdDesc(Long usuarioId);List<Notificacion> findByUsuarioIdAndLeidaFalseOrderByIdDesc(Long usuarioId);}